function assertTeacherNames_(d,c,approvals=[]){const rows=new Map((c.people||[]).map(t=>[t.id,t]));d.teachers.forEach(t=>rows.set(t.id,t));const used=new Map();for(const t of rows.values()){const name=(t.name||profileName_(teacherProfile_(t),t.mk)).trim().toLowerCase();if(!name)continue;if(used.has(name)&&used.get(name)!==t.id)error_(409,'Name conflict — Admin resolution required: '+t.name);used.set(name,t.id);}}
